function findNext(){breakTyping();const q=$('find').value;if(!q)return setMessage('Enter text to find.');const from=bounds(carets.at(-1))[1],lower=text.toLocaleLowerCase(),needle=q.toLocaleLowerCase();let at=lower.indexOf(needle,from);if(at<0)at=lower.indexOf(needle);if(at<0)return setMessage(`No matches for “${q}”.`);carets=[{anchor:at,head:at+q.length,goal:null}];setMessage();reveal(at);status()}
function currentMatch(){const q=$('find').value,[a,b]=bounds(carets.at(-1));return q&&text.slice(a,b).toLocaleLowerCase()===q.toLocaleLowerCase()?[a,b]:null}
