async function request(url,options){const res=await fetch(url,options),data=await res.json().catch(()=>({error:'Invalid server response.'}));if(!res.ok)throw new Error(data.error||`Request failed (${res.status}).`);return data}
async function save(){if(text===saved)return;setMessage();$('save').disabled=true;$('save-state').textContent='Saving…';try{const result=await request(`/api/documents/${encodeURIComponent(doc.id)}`,{method:'PUT',headers:{'content-type':'application/json'},body:JSON.stringify({id:doc.id,baseRevision:revision,content:text})});revision=result.revision;saved=text;status();await loadRevisions()}catch(e){setMessage(e.message);status()}}
async function loadRevisions(){const rows=await request(`/api/documents/${encodeURIComponent(doc.id)}/revisions`);$('revision-list').replaceChildren(...rows.map(row=>{const b=document.createElement('button');b.className='revision-item';const strong=document.createElement('strong'),time=document.createElement('time');strong.textContent=`Revision ${row.revision}${row.revision===revision?' · current':''}`;time.textContent=new Date(row.created_at).toLocaleString();b.append(strong,time);b.onclick=()=>preview(row.revision);return b}))}
async function preview(number){try{previewed=await request(`/api/documents/${encodeURIComponent(doc.id)}/revisions/${number}`);$('preview-title').textContent=`Revision ${number} preview`;$('preview-content').textContent=previewed.content;$('preview').showModal()}catch(e){setMessage(e.message)}}
